import pt.realmeconomy.service.*;
import pt.realmeconomy.data.EconomyData;
@GameTestHolder("realmeconomycolony") @PrefixGameTestTemplate(false)
public final class ColonyGameTests {
 @GameTest(template="colony_empty",timeoutTicks=200) public static void nativeColonyOwnerDepositsAndWithdrawsWithoutMinting(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){h.assertTrue(!f.owner.hasPermissions(2),"Owner must be non-OP");f.open();f.transfer(f.owner,true,20000);h.assertTrue(ChroniclesBridge.balance(f.owner)==80000&&f.data.colonies().account(f.key()).balance()==20000,"Deposit failed conservation");f.transfer(f.owner,false,5000);h.assertTrue(ChroniclesBridge.balance(f.owner)==85000&&f.data.colonies().account(f.key()).balance()==15000,"Withdrawal failed conservation");h.assertTrue(f.data.journal()==null,"Native receipt did not finish");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void aColonyFriendCanContributeButCannotWithdraw(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){ColonyService.open(f.friend,f.pos);f.transfer(f.friend,true,10000);f.transfer(f.friend,false,1000);h.assertTrue(ChroniclesBridge.balance(f.friend)==190000&&f.data.colonies().account(f.key()).balance()==10000,"Friend withdrew colony funds");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void outsidersCannotReadOrUseTheColonyBank(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){boolean rejected=false;try{ColonyService.open(f.outsider,f.pos);}catch(RuntimeException e){rejected=true;}h.assertTrue(rejected&&f.data.colonies().account(f.key()).balance()==0,"An outsider opened the bank");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void removingNativeMembershipRevokesTheSessionImmediately(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.open();var body=f.request(f.owner);body.addProperty("amount",1000);f.colony.getPermissions().setOwner(f.friend);f.colony.getPermissions().removePlayer(f.owner.getUUID());ColonyService.action(f.owner,"clnDeposit",body.toString());h.assertTrue(f.data.colonies().account(f.key()).balance()==0&&ChroniclesBridge.balance(f.owner)==100000,"Removed member retained finance access");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void nativeOfficerRightsAuthorizeColonyManagement(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.colony.getPermissions().setPlayerRank(f.friend.getUUID(),f.colony.getPermissions().getRankOfficer(),h.getLevel());h.assertTrue(ColonyAccess.manager(f.friend,f.colony),"Native officer was not recognised");f.open();f.transfer(f.owner,true,10000);ColonyService.open(f.friend,f.pos);f.transfer(f.friend,false,5000);h.assertTrue(f.data.colonies().account(f.key()).balance()==5000&&ChroniclesBridge.balance(f.friend)==205000,"Officer withdrawal was not conserved");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void sameNonceCannotWithdrawTwice(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.open();f.transfer(f.owner,true,10000);f.resetLimit(f.owner);var body=f.request(f.owner);body.addProperty("amount",5000);ColonyService.action(f.owner,"clnWithdraw",body.toString());f.resetLimit(f.owner);ColonyService.action(f.owner,"clnWithdraw",body.toString());h.assertTrue(ChroniclesBridge.balance(f.owner)==95000&&f.data.colonies().account(f.key()).balance()==5000,"Replayed nonce withdrew twice");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void malformedClientAmountsNeverChangeBalances(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.open();for(String amount:List.of("-1","0","1.5","9999999999999999999999999999","\"100\"")){f.resetLimit(f.owner);var p=f.request(f.owner);p.add("amount",com.google.gson.JsonParser.parseString(amount));ColonyService.action(f.owner,"clnDeposit",p.toString());}h.assertTrue(ChroniclesBridge.balance(f.owner)==100000&&f.data.colonies().account(f.key()).balance()==0,"Malformed amount mutated money");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void exportsConsumeActualItemsAndPayOnlyTheColony(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.open();var order=f.data.colonies().account(f.key()).orders().getFirst();var item=net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse(order.item()));int left=order.quantity(),slot=0;while(left>0){int n=Math.min(left,64);f.owner.getInventory().setItem(slot++,new ItemStack(item,n));left-=n;}var body=f.request(f.owner);body.addProperty("order",order.id());ColonyService.action(f.owner,"clnExport",body.toString());h.assertTrue(f.data.colonies().account(f.key()).balance()==order.cents()&&ChroniclesBridge.balance(f.owner)==100000&&f.owner.getInventory().countItem(item)==0,"Export did not consume goods and credit only the budget");f.resetLimit(f.owner);ColonyService.action(f.owner,"clnExport",body.toString());h.assertTrue(f.data.colonies().account(f.key()).balance()==order.cents(),"Export replay paid twice");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void namedOrMissingGoodsNeverCompleteAnExport(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.open();var order=f.data.colonies().account(f.key()).orders().getFirst();var item=net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse(order.item()));for(int i=0;i<10;i++){var stack=new ItemStack(item,64);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Keep this heirloom"));f.owner.getInventory().setItem(i,stack);}var body=f.request(f.owner);body.addProperty("order",order.id());ColonyService.action(f.owner,"clnExport",body.toString());h.assertTrue(f.data.colonies().account(f.key()).balance()==0&&f.owner.getInventory().countItem(item)==640,"Export consumed named goods or minted without delivery");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void breakingTheCofferPreservesFundsAndInvalidatesRequests(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.open();f.transfer(f.owner,true,10000);var body=f.request(f.owner);body.addProperty("amount",5000);h.getLevel().removeBlock(f.pos,false);ColonyService.action(f.owner,"clnWithdraw",body.toString());h.assertTrue(f.data.colonies().account(f.key()).balance()==10000&&ChroniclesBridge.balance(f.owner)==90000,"Broken coffer released or lost money");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void colonyFundsSurviveActualCompressedReload(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.open();f.transfer(f.owner,true,20000);f.reload();h.assertTrue(f.data.colonies().account(f.key()).balance()==20000&&f.data.snapshot().getInt("version")==3,"Reload lost the colony account");ColonyService.open(f.owner,f.pos);f.transfer(f.owner,false,20000);h.assertTrue(ChroniclesBridge.balance(f.owner)==100000&&f.data.colonies().account(f.key()).balance()==0,"Reopened funds could not be withdrawn exactly once");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void nativeBuildingMixinWaitsUntilItsInvoiceIsPaid(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.open();f.transfer(f.owner,true,10000);var order=f.order(WorkOrderType.BUILD,1);UUID id=((ColonyOrderAccess)order).realmEconomy$invoice();h.assertTrue(id!=null&&!order.canBuildIgnoringDistance(f.builder(),order.getLocation(),5),"Native work order ignored the unpaid invoice");f.pay(id.toString());h.assertTrue(order.canBuildIgnoringDistance(f.builder(),order.getLocation(),5)&&f.data.colonies().account(f.key()).balance()==7500,"Native work order did not unlock after its one payment");f.pay(id.toString());h.assertTrue(f.data.colonies().account(f.key()).balance()==7500,"Construction was paid twice");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void invoiceIdentityAndApprovalSurviveNativeOrderNbt(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.open();f.transfer(f.owner,true,20000);var order=f.order(WorkOrderType.UPGRADE,2);UUID id=((ColonyOrderAccess)order).realmEconomy$invoice();f.pay(id.toString());var nbt=new CompoundTag();order.write(nbt);var copy=new WorkOrderBuilding();copy.read(nbt,f.colony.getWorkManager());copy.onAdded(f.colony,true);h.assertTrue(id.equals(((ColonyOrderAccess)copy).realmEconomy$invoice())&&copy.canBuildIgnoringDistance(f.builder(),copy.getLocation(),5)&&f.data.colonies().account(f.key()).balance()==10000,"Native order restart lost its paid invoice");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void cancelledNativeWorkOrdersCannotBePaid(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.open();f.transfer(f.owner,true,20000);var order=f.order(WorkOrderType.BUILD,1);String id=((ColonyOrderAccess)order).realmEconomy$invoice().toString();f.colony.getWorkManager().getWorkOrders().remove(order.getID());f.pay(id);h.assertTrue(f.data.colonies().account(f.key()).balance()==20000&&!f.data.colonies().account(f.key()).invoice(id).paid(),"Cancelled construction still charged");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void repaymentStyleInterruptedWithdrawalRecoversOneCredit(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.open();f.transfer(f.owner,true,20000);f.owner.failOnSave=f.owner.saves+2;f.transfer(f.owner,false,5000);h.assertTrue(f.data.journal()!=null&&f.data.colonies().account(f.key()).balance()==20000,"Interrupted withdrawal lost the intent");var path=f.owner.server.getWorldPath(net.minecraft.world.level.storage.LevelResource.PLAYER_DATA_DIR).resolve(f.owner.getUUID()+".dat");var saved=NbtIo.readCompressed(path,NbtAccounter.unlimitedHeap());f.owner.failOnSave=0;f.owner.load(saved);f.owner.getPersistentData().remove(TradeJournal.RECEIPT_KEY);if(saved.getCompound("NeoForgeData").contains(TradeJournal.RECEIPT_KEY))f.owner.getPersistentData().put(TradeJournal.RECEIPT_KEY,saved.getCompound("NeoForgeData").getCompound(TradeJournal.RECEIPT_KEY).copy());TradeJournal.recover(f.owner);TradeJournal.recover(f.owner);h.assertTrue(f.data.journal()==null&&ChroniclesBridge.balance(f.owner)==85000&&f.data.colonies().account(f.key()).balance()==15000,"Interrupted withdrawal duplicated or lost money");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void legacyVersionTwoMigratesWithoutLosingServices(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){var old=f.previous.snapshot();old.putInt("version",2);old.remove("colonies");old.remove("colonySalt");var ctor=EconomyData.class.getDeclaredConstructor(Path.class,CompoundTag.class);ctor.setAccessible(true);var next=ctor.newInstance(f.directory.resolve("migration.dat"),old);h.assertTrue(next.snapshot().getInt("version")==3&&next.rulesSnapshot().equals(f.previous.rulesSnapshot())&&next.collection("jobs").equals(f.previous.collection("jobs")),"Migration lost original economic data");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void balanceLimitsAndExportClockAreServerControlled(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.open();var before=f.data.colonies();var body=f.request(f.owner);body.addProperty("amount",1000);body.addProperty("balance",999999);ColonyService.action(f.owner,"clnDeposit",body.toString());h.assertTrue(f.data.colonies().equals(before),"Client controlled a financial snapshot");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void cofferHasARealRecipeAndRegisteredCreativeItem(GameTestHelper h){h.assertTrue(pt.realmeconomy.block.EconomyBlocks.COLONY_ITEM.get() instanceof BlockItem&&h.getLevel().getRecipeManager().byKey(net.minecraft.resources.ResourceLocation.parse("realmeconomy:colony_coffer")).isPresent(),"Physical coffer or crafting recipe missing");if(Boolean.getBoolean("colony.selectedAddons")){for(String id:List.of("bitsandbobs","byzantine","colonyrank","mapcolonies","smallcolonies","smallcoloniesme","fzzy_config","kotlinforforge"))h.assertTrue(net.neoforged.fml.ModList.get().isLoaded(id),"Selected addon missing: "+id);System.out.println("COLONY_ADDONS_VERIFIED");}h.succeed();System.out.println("COLONY_NATIVE_PASSED");}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void nativeRecruitmentRequiresItsPaidPermitAndKeepsOriginalItems(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){
  var v=(com.minecolonies.api.colony.IVisitorData)f.colony.getVisitorManager().createAndRegisterCivilianData();v.setName("Travelling Carpenter");v.setRecruitCosts(new ItemStack(Items.BREAD));v.setLastPosition(f.pos);
  var entity=com.minecolonies.api.entity.ModEntities.VISITOR.create(h.getLevel());entity.setPos(f.owner.position());v.setEntity(entity);entity.setCivilianData(v);entity.setUUID(v.getUUID());
  f.owner.getInventory().setItem(0,new ItemStack(Items.BREAD));f.open();f.transfer(f.owner,true,10000);
  var interaction=new com.minecolonies.core.colony.interactionhandling.RecruitmentInteraction(Component.literal("Visitor"),com.minecolonies.api.colony.interactionhandling.ChatPriority.IMPORTANT);
  int response=0;for(int i=0;i<interaction.getPossibleResponses().size();i++)if(interaction.getPossibleResponses().get(i).getContents() instanceof net.minecraft.network.chat.contents.TranslatableContents text&&text.getKey().equals("com.minecolonies.coremod.gui.chat.recruit"))response=i;
  interaction.onServerResponseTriggered(response,f.owner,v);h.assertTrue(f.colony.getCitizenManager().getCurrentCitizenCount()==0&&f.owner.getInventory().countItem(Items.BREAD)==1,"Recruitment bypassed its unpaid native mixin");
  f.pay(ColonyAccess.recruitId(v).toString());h.getLevel().random.setSeed(0);interaction.onServerResponseTriggered(response,f.owner,v);
  h.assertTrue(f.colony.getCitizenManager().getCurrentCitizenCount()==1&&f.owner.getInventory().countItem(Items.BREAD)==0&&f.data.colonies().account(f.key()).balance()==7500,"Paid recruitment failed native colonist creation or material consumption");
 }h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void deletingAFundedColonyIsRefusedUntilTheBudgetIsWithdrawn(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.open();f.transfer(f.owner,true,10000);com.minecolonies.api.colony.IColonyManager.getInstance().deleteColonyByWorld(f.colony.getID(),false,h.getLevel());h.assertTrue(com.minecolonies.api.colony.IColonyManager.getInstance().getColonyByWorld(f.colony.getID(),h.getLevel())==f.colony&&f.data.colonies().account(f.key()).balance()==10000,"Native deletion orphaned a funded budget");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void finalLedgerWriteFailureRecoversFromTheActualSavedReceipt(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){
  f.open();f.transfer(f.owner,true,20000);Path file=f.data.path(),backup=file.resolveSibling("prepared.dat");int target=f.owner.saves+2;f.owner.savedHook=()->{if(f.owner.saves==target)try{Files.move(file,backup);Files.createDirectory(file);}catch(Exception e){throw new IllegalStateException(e);}};
  f.transfer(f.owner,false,5000);f.owner.savedHook=null;h.assertTrue(f.data.journal()!=null&&ChroniclesBridge.balance(f.owner)==85000,"Final bank failure did not retain a committed player receipt");Files.delete(file);Files.move(backup,file);f.reload();TradeJournal.recover(f.owner);TradeJournal.recover(f.owner);h.assertTrue(f.data.journal()==null&&f.data.colonies().account(f.key()).balance()==15000&&ChroniclesBridge.balance(f.owner)==85000,"After-receipt recovery duplicated a withdrawal");
 }h.succeed();}

 @GameTest(template="colony_empty",timeoutTicks=200) public static void growingLedgerSurvivesBeyondTheNbtStringLimit(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){var state=f.data.colonies();for(int i=0;i<300;i++){var id=UUID.randomUUID().toString();state=ColonyLedger.invoice(state,f.key(),new ColonyLedger.Invoice(id,"BUILD","A long building name for a growing and persistent colony "+i,"32, 90, 15 · 1",2500,false,System.currentTimeMillis()),System.currentTimeMillis());}h.assertTrue(ColonyLedger.encode(state).getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65535,"Stress fixture must exceed NBT string capacity");f.data.colonies(state);f.reload();h.assertTrue(f.data.colonies().equals(state)&&f.data.snapshot().contains("colonies",Tag.TAG_BYTE_ARRAY),"Growing bank exceeded NBT storage capacity");}h.succeed();}

 @GameTest(template="colony_empty",timeoutTicks=200) public static void restartingTheSameConstructionReusesItsPaidPermit(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){f.open();f.transfer(f.owner,true,20000);var first=f.order(WorkOrderType.BUILD,1);var id=((ColonyOrderAccess)first).realmEconomy$invoice();f.pay(id.toString());f.colony.getWorkManager().getWorkOrders().remove(first.getID());var next=f.order(WorkOrderType.BUILD,1);h.assertTrue(id.equals(((ColonyOrderAccess)next).realmEconomy$invoice())&&f.data.colonies().account(f.key()).balance()==17500&&next.canBuildIgnoringDistance(f.builder(),next.getLocation(),5),"Restarting the same build double-charged or lost its permit");}h.succeed();}
 @GameTest(template="colony_empty",timeoutTicks=200) public static void zeroConfiguredConstructionFeeDoesNotBlockNativeBuilders(GameTestHelper h)throws Exception{try(var f=new ColonyFixture(h)){var s=f.data.colonies();f.data.colonies(s.policy(new ColonyLedger.Policy(true,25000,25000,5,0,0),System.currentTimeMillis()));var order=f.order(WorkOrderType.BUILD,1);h.assertTrue(order.canBuildIgnoringDistance(f.builder(),order.getLocation(),5)&&f.data.colonies().account(f.key()).balance()==0,"A zero fee still blocked native construction");}h.succeed();}

}
